import type { Metadata, Viewport } from "next";
import type { ReactNode } from "react";
import { Analytics } from "@/components/site/Analytics";
import { Footer } from "@/components/site/Footer";
import { Header } from "@/components/site/Header";
import { ScrollSpy } from "@/components/site/ScrollSpy";
import { SmoothScroll } from "@/components/site/SmoothScroll";
import { googleSans, googleSansCode } from "./fonts";
import { themeScript } from "./theme-script";
import { site } from "@/lib/site";
import "./globals.css";

/** Share card, generated by `pnpm og` into public/og.jpg. */
const ogAlt =
  "Flutter Philippines: join thousands of developers, designers and founders building apps with Flutter, Dart and AI.";

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: { default: site.name, template: `%s | ${site.name}` },
  description:
    "A community of designers, developers and founders in the Philippines building apps with Flutter, Dart and AI. Events, learning resources and ways to join.",
  applicationName: site.name,
  alternates: { canonical: "/" },
  openGraph: {
    siteName: site.name,
    title: site.name,
    description:
      "Join thousands of developers, designers and founders building apps with Flutter, Dart and AI.",
    url: "/",
    locale: site.locale,
    type: "website",
    images: [{ url: "/og.jpg", width: 1200, height: 630, alt: ogAlt }],
  },
  twitter: {
    card: "summary_large_image",
    site: "@flutter_ph",
    title: site.name,
    description:
      "Join thousands of developers, designers and founders building apps with Flutter, Dart and AI.",
    images: [{ url: "/og.jpg", alt: ogAlt }],
  },
};

export const viewport: Viewport = {
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#e8ebf0" },
    { media: "(prefers-color-scheme: dark)", color: "#e8ebf0" },
  ],
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html
      lang="en-PH"
      className={`${googleSans.variable} ${googleSansCode.variable}`}
      suppressHydrationWarning
    >
      <head>
        {/* Sets data-theme before paint. suppressHydrationWarning covers only this attribute. */}
        <script dangerouslySetInnerHTML={{ __html: themeScript }} />
      </head>
      <body className="min-h-dvh antialiased">
        <a
          href="#main"
          className="fixed top-3 left-3 z-[60] -translate-y-24 rounded-pill bg-ink px-5 py-3 text-on-ink focus:translate-y-0"
        >
          Skip to content
        </a>
        <Header />
        {children}
        <Footer />
        <SmoothScroll />
        <ScrollSpy />
        <Analytics />
      </body>
    </html>
  );
}
